void __stdcall CHATDLG_RefreshGameNameDisplay() {
    int nClearCount;
    BOOL bActive;
    uint16_t* pwszClearCursor;
    uint16_t awszGameNames[512];
    char aszGameNames[512];
    char cCurrent;
    for (nClearCount = 0; nClearCount < 0x200; nClearCount++) {
      awszGameNames[nClearCount] = L'\0';
    }

    if (!pGameListCache) {
      return;
    }

    aszGameNames[0] = '\0';
    char* pszNameNode;
    pszNameNode = (char*)gpChatPlayerNameListHead;
    if (gpChatPlayerNameListHead) {
      int nUsedLen = 0;
      do {
        if (nUsedLen >= 0x200) {
          break;
        }

        strncat(aszGameNames, pszNameNode, 0x200 - nUsedLen);
        int nLen = (int)strlen(aszGameNames);
        pszNameNode = *(char**)(pszNameNode + 0x204);
        nUsedLen = nLen;
      } while (pszNameNode);

      if (aszGameNames[0] != '\0') {
        bActive = 0;
        goto update_display;
      }
    }

    bActive = 1;
    update_display:
    D2Win::Src::D2WinMain::D2WINMAIN_SetControlActive(ghWndGameNameEditBox, bActive);
    D2Lang::Unicode::UNISYS::STRING_ConvertCharToWchar(awszGameNames, aszGameNames, 0x200);
    D2Win::Src::D2WinTextBox::SetText(pGameListCache, awszGameNames, 1, false, 0);
}

